CREATE TABLE IF NOT EXISTS products (id BIGINT PRIMARY KEY, name VARCHAR(100) NOT NULL, description VARCHAR(400) NOT NULL, price DECIMAL(12,2) NOT NULL, stock INT NOT NULL CHECK (stock>=0), image VARCHAR(100) NOT NULL);
CREATE TABLE IF NOT EXISTS reservations (order_id VARCHAR(80) PRIMARY KEY, product_id BIGINT NOT NULL, quantity INT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
